// Literal port of the team's Casa3DSDK (module mirrors). Generated by codemod and reviewed; see MIGRATION.md.
import type { Kernel, Shared } from './kernel-types.js';

export function installMirrors(K: Kernel, shared: Shared): void {
  const { DOC, THREE, Reflector, MIRRORS, Y0, _Y, roomAt } = K;
  // ===== mirrors: real reflection (Reflector) only on the nearest mirror, only when the camera is in the same room; the others use a cube environment map. 'game' quality: cube only, everything merged per group =====
  shared.mirrorEnv = null; shared.mirrorMat = null;
  function mirrorEnv() { // cheap procedural cube: light sky/ceiling on top, warm walls, dark floor (only once)
    if (shared.mirrorEnv) return shared.mirrorEnv;
    const mk = f => { const c = DOC.createElement('canvas'); c.width = c.height = 64; const g = c.getContext('2d'); f(g); return c; };
    const grad = (a, b) => g => { const q = g.createLinearGradient(0, 0, 0, 64); q.addColorStop(0, a); q.addColorStop(1, b); g.fillStyle = q; g.fillRect(0, 0, 64, 64); };
    const side = (j, k) => g => { grad('#e9e4da', '#b8ae9c')(g); if (j) { g.fillStyle = 'rgba(255,255,255,.75)'; g.fillRect(14, 12, 22, 30); g.fillStyle = 'rgba(120,150,180,.35)'; g.fillRect(18, 16, 14, 22); } if (k) { g.fillStyle = 'rgba(90,70,50,.5)'; g.fillRect(36, 22, 18, 42); } };
    const faces = [side(1, 0), side(0, 1), mk(g => { grad('#f3efe6', '#e2ddd2')(g); g.fillStyle = 'rgba(255,255,230,.9)'; g.fillRect(24, 24, 16, 16); }), mk(g => grad('#6d6455', '#4e463a')(g)), side(0, 0), side(1, 1)]
      .map(f => (typeof f === 'function' ? mk(f) : f));
    const t = new THREE.CubeTexture(faces); t.colorSpace = THREE.SRGBColorSpace; t.needsUpdate = true; shared.mirrorEnv = t;
    shared.mirrorMat = new THREE.MeshStandardMaterial({ color: 0xf4f6f8, metalness: 1, roughness: 0.06, envMap: t, envMapIntensity: 1.0 });
    return t;
  }
  const newMirrorState = () => ({ list: [], active: null, tmp: new THREE.Vector3(), house: null });
  shared.mirrors = newMirrorState();
  function assembleMirrors(groups) {
    shared.mirrors.list.length = 0; shared.mirrors.active = null;
    if (!MIRRORS.length) return;
    mirrorEnv();
    if (shared.quality === 'game' || !Reflector) { // no real reflection: one plane with the cube per mirror, all merged into one mesh per parent group
      const by = new Map(), m4 = new THREE.Matrix4(), qy = new THREE.Quaternion(), um = new THREE.Vector3(1, 1, 1), ps = new THREE.Vector3(), nm = new THREE.Matrix3(), v = new THREE.Vector3();
      for (const E of MIRRORS) {
        const geo = new THREE.PlaneGeometry(E.w, E.h); m4.compose(ps.set(E.x, E.y, E.z), qy.setFromAxisAngle(_Y, E.ry), um); nm.getNormalMatrix(m4);
        let B = by.get(E.parent); if (!B) by.set(E.parent, B = { P: [], N: [], U: [], I: [], nv: 0 });
        const pa = geo.attributes.position, na = geo.attributes.normal, ua = geo.attributes.uv;
        for (let i = 0; i < pa.count; i++) { v.fromBufferAttribute(pa, i).applyMatrix4(m4); B.P.push(v.x, v.y, v.z); v.fromBufferAttribute(na, i).applyMatrix3(nm).normalize(); B.N.push(v.x, v.y, v.z); B.U.push(ua.getX(i), ua.getY(i)); }
        for (const k of geo.index.array) B.I.push(B.nv + k); B.nv += pa.count; geo.dispose();
      }
      for (const [parent, B] of by) {
        const g = new THREE.BufferGeometry(); g.setAttribute('position', new THREE.Float32BufferAttribute(B.P, 3)); g.setAttribute('normal', new THREE.Float32BufferAttribute(B.N, 3)); g.setAttribute('uv', new THREE.Float32BufferAttribute(B.U, 2)); g.setIndex(B.I); g.computeBoundingSphere();
        const m = new THREE.Mesh(g, shared.mirrorMat); m.name = 'mirror/environment'; m.userData.part = 'mirror'; (groups[parent] || (groups[parent] = new THREE.Group())).add(m);
      }
      return;
    }
    for (const E of MIRRORS) {
      const g = new THREE.Group(); g.position.set(E.x, E.y, E.z); g.rotation.y = E.ry; g.name = 'mirror';
      g.userData.part = 'mirror'; g.userData.room = E.room;
      const geo = new THREE.PlaneGeometry(E.w, E.h);
      const fake = new THREE.Mesh(geo, shared.mirrorMat); fake.userData.part = 'mirror'; fake.name = 'mirror/environment'; g.add(fake);
      let real = null;
      try {
        real = new Reflector(geo, { textureWidth: 512, textureHeight: Math.round(512 * Math.max(0.5, Math.min(2, E.h / E.w))), color: 0xdfe6ea, clipBias: 0.002, multisample: 0 });
        real.position.z = 0.0015; real.visible = false; real.name = 'mirror/reflection'; real.userData.part = 'mirror'; g.add(real);
      } catch (e) { console.warn('mirror real', e); }
      (groups[E.parent] || (groups[E.parent] = new THREE.Group())).add(g);
      shared.mirrors.list.push({ E, g, fake, real });
    }
  }
  function floorAtY(y) { const A = shared.ctx.r.floors; let f = 0; for (let i = 0; i < A.length; i++) if (y >= A[i].y0 - 0.2) f = i; return f; }
  function chooseMirror(camera) { // call before drawing the camera (scene.onBeforeRender): turns on the real reflection of the mirror of the room the camera is in
    if (!shared.mirrors.list.length) return;
    let target = null;
    if (shared.mirrors.house && shared.ctx.r) {
      shared.mirrors.tmp.copy(camera.position); shared.mirrors.house.worldToLocal(shared.mirrors.tmp);
      const f = floorAtY(shared.mirrors.tmp.y), c = roomAt(f, shared.mirrors.tmp.x, shared.mirrors.tmp.z);
      if (c && shared.mirrors.tmp.y > Y0(f) && shared.mirrors.tmp.y < Y0(f) + 4) {
        let best = 1e9;
        for (const m of shared.mirrors.list) { if (m.E.room !== c.id || m.E.floor !== f || !m.g.parent || !m.g.parent.visible) continue; const d = Math.hypot(m.E.x - shared.mirrors.tmp.x, m.E.z - shared.mirrors.tmp.z); if (d < best) { best = d; target = m; } }
      }
    }
    if (target === shared.mirrors.active) return;
    shared.mirrors.active = target;
    for (const m of shared.mirrors.list) { const on = m === target && !!m.real; if (m.real) m.real.visible = on; m.fake.visible = !on; }
  }
  Object.assign(K, { mirrorEnv, newMirrorState, assembleMirrors, floorAtY, chooseMirror });
}
